function CountSpaces(text: string): int
    requires text != null
    ensures 0 <= result <= text.Length
{
    var count := 0;
    var i := 0;
    while i < text.Length
        invariant 0 <= i <= text.Length
        invariant count == Count(text, ' ')
    {
        if text[i] == ' ' {
            count := count + 1;
        }
        i := i + 1;
    }
    return count;
}

function CountConsecutiveSpaces(text: string): int
    requires text != null
    ensures 0 <= result <= text.Length
{
    var count := 0;
    var i := 0;
    while i < text.Length
        invariant 0 <= i <= text.Length
        invariant count >= 0
    {
        if i + 1 < text.Length && text[i] == ' ' && text[i + 1] == ' ' {
            count := count + 1;
            while i + 1 < text.Length && text[i] == ' ' {
                i := i + 1;
            }
        }
        i := i + 1;
    }
    return count;
}
